// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

interface IVaultMock {
    function setUtilization(uint256 u) external;
    function setCurrentIndex(uint256 idx) external;
    function currentUtilizationIndex(address _asset) external view returns (uint256);
    function utilization(address _asset) external view returns (uint256);
    function currentUtilizationIndex_writeable(address _asset) external returns (uint256);
}

contract VaultMock {
    uint256 public util;
    uint256 public idx;
    function setUtilization(uint256 u) external { util = u; }
    function setCurrentIndex(uint256 _idx) external { idx = _idx; }
    function currentUtilizationIndex(address) external view returns (uint256) { return idx; }
    function utilization(address) external view returns (uint256) { return util; }
}

contract InvMutTest is Test {
    VaultAdapter c;
    VaultMock vault;

    function setUp() public { c = new VaultAdapter(); vault = new VaultMock(); }

    function testFuzz_property(address asset, uint256 vaultIndex, uint256 reportedUtilization) public {
        vaultIndex = bound(vaultIndex, 0, type(uint256).max / 4);
        reportedUtilization = bound(reportedUtilization, 0, 1e27 - 1);

        vault.setCurrentIndex(vaultIndex);
        vault.setUtilization(reportedUtilization);

        vm.warp(block.timestamp + 1000);
        try c.rate(address(vault), asset) returns (uint256) {
        } catch {
            return;
        }

        uint256 recordedLastUpdate = block.timestamp;

        vm.warp(recordedLastUpdate - 1);

        bool okRef;
        uint256 refAnswer;
        try c.rate(address(vault), asset) returns (uint256 ans) {
            okRef = true;
            refAnswer = ans;
        } catch {
            okRef = false;
            refAnswer = 0;
        }

        vault.setCurrentIndex(vaultIndex + 1);

        bool okAfter;
        uint256 afterAnswer;
        try c.rate(address(vault), asset) returns (uint256 ans2) {
            okAfter = true;
            afterAnswer = ans2;
        } catch {
            okAfter = false;
            afterAnswer = 0;
        }

        assertTrue((okRef == okAfter) && (!okRef || refAnswer == afterAnswer));
    }
}
